CREATE SCHEMA IF NOT EXISTS private;
REVOKE ALL ON SCHEMA private FROM PUBLIC;
CREATE ROLE crm_runtime NOLOGIN NOBYPASSRLS;
GRANT USAGE ON SCHEMA public,private TO crm_runtime;
CREATE TABLE public.users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE private.sessions(id text PRIMARY KEY,user_id uuid NOT NULL REFERENCES public.users(id),expires_at timestamptz NOT NULL);
CREATE TABLE public.tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),name text NOT NULL,grants text[] NOT NULL DEFAULT '{}',UNIQUE(tenant_id,id),UNIQUE(tenant_id,name));
CREATE TABLE public.permissions(key text PRIMARY KEY);
INSERT INTO public.permissions VALUES ('crm.read'),('crm.write'),('team.manage'),('settings.manage'),('ai.run');
CREATE TABLE public.memberships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),user_id uuid NOT NULL REFERENCES public.users(id),role_id uuid NOT NULL,UNIQUE(tenant_id,user_id),FOREIGN KEY(tenant_id,role_id) REFERENCES public.roles(tenant_id,id));
CREATE INDEX memberships_user ON public.memberships(user_id,tenant_id);
CREATE TABLE public.tenant_settings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid UNIQUE NOT NULL REFERENCES public.tenants(id),locale text NOT NULL DEFAULT 'fa',currency text NOT NULL DEFAULT 'IRR',timezone text NOT NULL DEFAULT 'Asia/Tehran');
CREATE FUNCTION private.identity() RETURNS uuid LANGUAGE sql STABLE SET search_path='' AS $$ SELECT nullif(current_setting('app.user_id',true),'')::uuid $$;
CREATE FUNCTION private.can(t uuid,p text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT private.identity() IS NOT NULL AND EXISTS(SELECT 1 FROM public.memberships m JOIN public.roles r ON r.id=m.role_id AND r.tenant_id=m.tenant_id WHERE m.user_id=private.identity() AND m.tenant_id=t AND (p='' OR p=ANY(r.grants))) $$;
REVOKE ALL ON FUNCTION private.can(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION private.can(uuid,text),private.identity() TO crm_runtime;
CREATE TABLE public.accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),kind text NOT NULL DEFAULT 'company' CHECK(kind IN ('company','person')),email text NOT NULL DEFAULT '',phone text NOT NULL DEFAULT '',description text NOT NULL DEFAULT '');
CREATE INDEX accounts_tenant_created ON public.accounts(tenant_id,created_at);
CREATE TABLE public.contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),email text NOT NULL DEFAULT '',phone text NOT NULL DEFAULT '',account_id uuid,FOREIGN KEY(tenant_id,account_id) REFERENCES public.accounts(tenant_id,id));
CREATE INDEX contacts_tenant_created ON public.contacts(tenant_id,created_at);
CREATE TABLE public.leads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),email text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','qualified','lost','converted')),source text NOT NULL DEFAULT '');
CREATE INDEX leads_tenant_created ON public.leads(tenant_id,created_at);
CREATE TABLE public.pipelines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id));
CREATE INDEX pipelines_tenant_created ON public.pipelines(tenant_id,created_at);
CREATE TABLE public.pipeline_stages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),pipeline_id uuid NOT NULL,position integer NOT NULL CHECK(position>=0),probability integer NOT NULL DEFAULT 0 CHECK(probability BETWEEN 0 AND 100),UNIQUE(tenant_id,pipeline_id,id),FOREIGN KEY(tenant_id,pipeline_id) REFERENCES public.pipelines(tenant_id,id));
CREATE INDEX pipeline_stages_tenant_created ON public.pipeline_stages(tenant_id,created_at);
CREATE TABLE public.deals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),account_id uuid,pipeline_id uuid NOT NULL,stage_id uuid NOT NULL,value numeric(18,2) NOT NULL DEFAULT 0 CHECK(value>=0),currency text NOT NULL DEFAULT 'IRR',status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','won','lost')),FOREIGN KEY(tenant_id,account_id) REFERENCES public.accounts(tenant_id,id),FOREIGN KEY(tenant_id,pipeline_id,stage_id) REFERENCES public.pipeline_stages(tenant_id,pipeline_id,id));
CREATE INDEX deals_tenant_created ON public.deals(tenant_id,created_at);
CREATE TABLE public.activities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),kind text NOT NULL DEFAULT 'call',account_id uuid,description text NOT NULL DEFAULT '',FOREIGN KEY(tenant_id,account_id) REFERENCES public.accounts(tenant_id,id));
CREATE INDEX activities_tenant_created ON public.activities(tenant_id,created_at);
CREATE TABLE public.tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),status text NOT NULL DEFAULT 'todo' CHECK(status IN ('todo','doing','done')),due_at timestamptz,description text NOT NULL DEFAULT '');
CREATE INDEX tasks_tenant_created ON public.tasks(tenant_id,created_at);
CREATE TABLE public.notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),body text NOT NULL,account_id uuid,FOREIGN KEY(tenant_id,account_id) REFERENCES public.accounts(tenant_id,id));
CREATE INDEX notes_tenant_created ON public.notes(tenant_id,created_at);
CREATE TABLE public.audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),actor_id uuid NOT NULL REFERENCES public.users(id),action text NOT NULL,resource text NOT NULL,record_id uuid,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE private.invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),email text NOT NULL,role_id uuid NOT NULL,token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,accepted_at timestamptz,FOREIGN KEY(tenant_id,role_id) REFERENCES public.roles(tenant_id,id));
CREATE TABLE public.ai_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),created_at timestamptz NOT NULL DEFAULT now(),status text NOT NULL DEFAULT 'pending',requested_by uuid NOT NULL REFERENCES public.users(id));
CREATE TABLE public.tool_registry(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),created_at timestamptz NOT NULL DEFAULT now(),name text NOT NULL,permission text NOT NULL,sensitive boolean NOT NULL DEFAULT true);
CREATE TABLE public.tool_permissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),created_at timestamptz NOT NULL DEFAULT now(),tool_id uuid NOT NULL REFERENCES public.tool_registry(id),role_id uuid NOT NULL);
CREATE TABLE public.approval_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),created_at timestamptz NOT NULL DEFAULT now(),run_id uuid NOT NULL REFERENCES public.ai_runs(id),status text NOT NULL DEFAULT 'pending',approved_by uuid REFERENCES public.users(id));
CREATE TABLE public.execution_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),created_at timestamptz NOT NULL DEFAULT now(),run_id uuid NOT NULL REFERENCES public.ai_runs(id),message text NOT NULL);
CREATE TABLE public.background_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),created_at timestamptz NOT NULL DEFAULT now(),status text NOT NULL DEFAULT 'pending',payload jsonb NOT NULL DEFAULT '{}');
ALTER TABLE public.accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.accounts FORCE ROW LEVEL SECURITY;
GRANT SELECT ON public.accounts TO crm_runtime;
CREATE POLICY scoped_read ON public.accounts FOR SELECT TO crm_runtime USING(private.can(tenant_id,'crm.read'));
GRANT INSERT,UPDATE,DELETE ON public.accounts TO crm_runtime;
CREATE POLICY scoped_write ON public.accounts FOR ALL TO crm_runtime USING(private.can(tenant_id,'crm.write')) WITH CHECK(private.can(tenant_id,'crm.write'));
