REVOKE ALL ON ALL TABLES IN SCHEMA public FROM anon,authenticated;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA private FROM PUBLIC;
GRANT EXECUTE ON FUNCTION private.can(uuid,text),private.identity() TO crm_runtime;
GRANT INSERT ON public.audit_logs TO crm_runtime;
CREATE POLICY audit_insert ON public.audit_logs FOR INSERT TO crm_runtime WITH CHECK(private.can(tenant_id,'crm.write') AND actor_id=private.identity());
